"""Separate the retained native ML effect from the new exact reductions."""
from s00_direct_common import *
from s14_prepare import sha
from s16_analyze import comparison

def main():
 p=read(HERE/'final_protocol.json.gz');assert all(read(HERE/f'deployment_test{i}.json')['complete'] for i in [0,1]);rows=[read(HERE/'deployment_test'/(c['id']+'.json.gz')) for c in p['cases']];initial=read(HERE/'protocol.json.gz');extended=[read(HERE/'model_test'/(c['id']+'.json.gz')) for c in initial['extended_cases']];native=[r for r in rows if r['group']=='native'];old=read(PRIOR/'trained_model/policy.json');candidate=read(HERE/'trained_model/policy.json')
 s=dict(complete=True,protocol_sha256=sha(HERE/'final_protocol.json.gz'),initial_protocol_sha256=sha(HERE/'protocol.json.gz'),all=comparison(rows),groups={g:comparison([r for r in rows if r['group']==g]) for g in sorted({r['group'] for r in rows})},native_ml=comparison(native,'fixed'),checks=sum(r['checks'] for r in rows+extended),extended_requests=len(extended),extended_completed=sum(all(r['success']['integrated']) for r in extended),extended_seconds=sum(r['median_seconds']['integrated'] for r in extended),model_enabled=old['enabled'],replacement_model_enabled=candidate['enabled'],retained_model={k:v for k,v in old.items() if k not in ['trees','failure_guard','minimum','maximum']},prediction_seconds=[r['results']['integrated'].get('prediction_seconds') for r in native],changed_native_requests=sum(r['results']['integrated'].get('selected_native_action')!=old['fixed'] for r in native),failed_applications={method:sum(sum(not v for v in r['success'][method]) for r in native) for method in ['integrated','fixed','previous']},native_failed_attempts={method:sum(sum(r['failed_attempts'][method]) for r in native) for method in ['integrated','fixed','previous']},rows=[{k:v for k,v in r.items() if k not in ['reference','results']} for r in rows+extended])
 write(HERE/'final_summary.json',s);print(json.dumps({k:v for k,v in s.items() if k not in ['rows','prediction_seconds','retained_model']}),flush=True)
if __name__=='__main__':main()
